import { createHash } from 'node:crypto';
import { homedir } from 'node:os';
import path from 'node:path';
import { BRAND } from '../brand.ts';
import { describeBranch, type IdentityFailure, type IndexEntry, type IndexSnapshot, type IndexStatus } from './snapshot.ts';

// The page and its plain-text twin. Static HTML regenerated by the tool; the
// page fetches itself on a timer and swaps its table in, so a browser tab left
// open follows along without losing the reader's place.

const STATUS_LABELS: Record<IndexStatus, string> = {
  running: 'Running',
  partial: 'Partial',
  stopped: 'Stopped',
  missing: 'Missing',
  unknown: 'Unknown'
};

const LEGEND = 'Running: every service answers. Partial: some do. Stopped: none do. ' +
  'Missing: the checkout is gone. Unknown: the state could not be read.';

const POLL_INTERVAL_MS = 15_000;
/**
 * Without scripting there is nothing to swap, so the whole page reloads
 * instead. A meta refresh cannot be paused, which WCAG 2.2.1 asks for; the
 * scripted path has the button, and this is the only way a page with no
 * scripting can follow a machine that keeps changing.
 */
const NOSCRIPT_REFRESH_SECONDS = 60;

/**
 * Whatever a config file, a branch name, or Git's own stderr put in a string,
 * made safe to print. Escape sequences can drive a terminal's cursor and
 * overwrite a line that said `Stopped` with one that says `Running`; a
 * right-to-left override reverses the rest of a row; a zero-width or soft
 * hyphen makes two different checkouts look identical.
 *
 * Whitespace becomes a space rather than a replacement character: Git's
 * messages are routinely multi-line, and a line break is a place to fold, not
 * something to hide. The zero-width joiners are kept: they carry meaning in
 * ordinary text.
 */
export function printable(value: string): string {
  return [...value].map((character) => {
    const code = character.codePointAt(0) ?? 0;
    if (code === 0x09 || code === 0x0a || code === 0x0d) return ' ';
    const control = code < 0x20 || code === 0x7f || (code >= 0x80 && code <= 0x9f) ||
      code === 0x2028 || code === 0x2029;
    // Every Unicode format character — bidi overrides, zero widths, the tag
    // block — except the joiners, which hold emoji together and are required
    // orthography in Persian and several Indic scripts.
    const invisible = /\p{Cf}/u.test(character) && character !== '\u200c' && character !== '\u200d';
    return control || invisible ? '\uFFFD' : character;
  }).join('');
}

export function escapeHtml(value: string): string {
  // Through `printable` first: escaping stops markup, not a right-to-left
  // override that reverses the rest of a row, or a zero-width space that makes
  // two checkouts look identical.
  return printable(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

/** `/Users/me/dev/x` → `~/dev/x`; paths outside the home are left alone. */
export function compactPath(target: string, home = homedir()): string {
  const relative = path.relative(home, target);
  return relative !== '' && !relative.startsWith('..') && !path.isAbsolute(relative)
    ? path.join('~', relative)
    : target;
}

/** Every row of one domain together, in the order the snapshot sorted them. */
function groupByDomain(entries: readonly IndexEntry[]): Map<string, IndexEntry[]> {
  const groups = new Map<string, IndexEntry[]>();
  for (const entry of entries) {
    const group = groups.get(entry.domain);
    if (group) group.push(entry);
    else groups.set(entry.domain, [entry]);
  }
  return groups;
}

/**
 * The project's name beside its domain — or the domain alone, when no card has
 * named the project. Grouping is by domain rather than project so a checkout
 * whose first `up` never finished, and which therefore has no card to name its
 * project, joins its project's table instead of starting a second one.
 */
function domainHeading(domain: string, entries: readonly IndexEntry[]): string {
  const named = [...new Set(entries.map((entry) => entry.project))]
    .filter((project) => project !== domain)
    .sort((left, right) => left.localeCompare(right, 'en'));
  return named.length === 0 ? domain : `${named.join(', ')} · ${domain}`;
}

/** Whole tables, in the order their headings read — which is not the order their domains sort in. */
function sections(entries: readonly IndexEntry[]): { heading: string; entries: IndexEntry[] }[] {
  return [...groupByDomain(entries)]
    .map(([domain, rows]) => ({ heading: domainHeading(domain, rows), entries: rows }))
    .sort((left, right) => left.heading.localeCompare(right.heading, 'en'));
}

function renderRow(entry: IndexEntry, unchecked: boolean): string {
  // Nothing was asked of a checkout Git says is gone; its services are not
  // "not answering", they are not there.
  const gone = entry.status === 'missing';
  const compact = entry.root === undefined ? '' : compactPath(entry.root);
  const checkout = entry.root === undefined
    ? '<span class="muted">—</span>'
    : `<span class="path" title="${escapeHtml(entry.root)}">${escapeHtml(compact)}</span>`;
  const services = entry.services.length === 0
    ? '<span class="muted">—</span>'
    // An explicit role: WebKit drops a bulletless list's role otherwise.
    : `<ul role="list">${entry.services.map((service) => {
      const contents = `<span class="service-label">${escapeHtml(service.label)}</span><span class="service-purpose">${escapeHtml(service.purpose)}</span>`;
      const target = escapeHtml(`${entry.host}-${service.name}`);
      // Nothing checked these, so the link is the only way left to find out:
      // never grey out a service whose state nobody has actually read.
      //
      // The named target keeps a service in the tab it already opened instead
      // of one tab per click, and that rules out `rel="noopener"`, which makes
      // a browser ignore the name. The price is a live `window.opener`: the
      // service — a container running the checked-out branch's own code — can
      // navigate this tab somewhere else. It cannot read the page, and the
      // page holds nothing the operator does not already know. What it can do
      // is navigate this tab somewhere else — reverse tabnabbing — on a page an
      // operator trusts to tell them what is running. The daily reuse is judged
      // worth that, for a tool whose services are all on this machine.
      if (unchecked) {
        return `<li><a class="service-link" href="${escapeHtml(service.url)}" target="${target}" title="${escapeHtml(service.url)}">${contents}<span class="sr-only"> (state unknown)</span></a></li>`;
      }
      return service.available
        ? `<li><a class="service-link" href="${escapeHtml(service.url)}" target="${target}" title="${escapeHtml(service.url)}">${contents}</a></li>`
        // A screen reader gets the word; sighted readers get the grey.
        : `<li><span class="service-link service-disabled" title="${escapeHtml(service.url)}">${contents}<span class="sr-only">${gone ? ' (checkout gone)' : ' (unavailable)'}</span></span></li>`;
    }).join('')}</ul>`;
  const guidance = entry.status === 'missing'
    ? `<div class="guidance">Checkout gone — <code>${escapeHtml(BRAND.name)} worktree remove ${escapeHtml(entry.slug)}</code></div>`
    : '';
  const branch = describeBranch(entry.branch);
  const name = branch.muted
    ? `<span class="muted">${escapeHtml(branch.text)}</span>`
    // The narrow layout hides the Checkout column, so the path rides along here.
    : `<strong>${escapeHtml(branch.text)}</strong>`;
  const echo = compact === '' ? '' : `<span class="path-compact">${escapeHtml(compact)}</span>`;
  return `<tr>
      <th scope="row">${name}${echo}<span class="host-compact"><code>${escapeHtml(entry.host)}</code></span></th>
      <td class="host"><code>${escapeHtml(entry.host)}</code></td>
      <td class="checkout">${checkout}</td>
      <td><span class="status status-${escapeHtml(entry.status)}">${STATUS_LABELS[entry.status]}</span>${guidance}</td>
      <td class="services">${services}</td>
    </tr>`;
}

/**
 * `Checkouts (3)` — the count is what tells one pinned tab from another. The
 * live-update script assigns this straight to `document.title`, so it must
 * stay text that reads the same escaped or not.
 */
function pageTitle(snapshot: IndexSnapshot): string {
  return `Checkouts (${snapshot.entries.length})`;
}

/**
 * What a freshly fetched copy of this page means for the copy on screen.
 * `foreign` is a document this module did not write, or one cut short —
 * distinct from `unchanged`, so a tab can tell "nothing to do" from "whatever
 * answered is not the index" and say so rather than sitting on stale rows.
 */
export type IndexUpdate =
  | { kind: 'unchanged' }
  | { kind: 'foreign' }
  | { kind: 'update'; stamp: string; title: string; main: string; shell: string; body: string };

/**
 * Pure string work over markup this module wrote, so the browser code below
 * can be tested here rather than only in a browser. It is embedded into the
 * page by `toString()`, so it must stay self-contained — no imports, no
 * closure over module scope, nothing a browser cannot run as written.
 *
 * `shell` fingerprints the stylesheet and this script, and `body` the rows, so
 * a tab can tell a newer berth's markup from its own and a regeneration that
 * changed something from one that changed nothing.
 */
export function planIndexUpdate(current: string | null, html: string): IndexUpdate {
  // Every sentinel is split, because this function's own source is embedded in
  // the page it parses: spelled out whole, each would also match the copy of
  // itself further down the document.
  const mainOpen = '<' + 'main';
  const mainClose = '</' + 'main>';
  const titleOpen = '<' + 'title>';
  const titleClose = '</' + 'title>';
  const stampTag = '<' + 'time datetime="';
  const shellTag = 'data-' + 'shell="';
  const bodyTag = 'data-' + 'body="';
  // An attribute value, refused when the tag ends before the closing quote: a
  // response cut mid-attribute must not read as the rest of the document.
  function value(tag: string, from: number): string | undefined {
    const at = html.indexOf(tag, from);
    if (at < 0) return undefined;
    const quote = html.indexOf('"', at + tag.length);
    const tagEnd = html.indexOf('>', at + tag.length);
    if (quote < 0 || (tagEnd >= 0 && tagEnd < quote)) return undefined;
    return html.slice(at + tag.length, quote);
  }
  const mainAt = html.indexOf(mainOpen);
  const titleAt = html.indexOf(titleOpen);
  if (mainAt < 0 || titleAt < 0) return { kind: 'foreign' };
  const mainTagEnd = html.indexOf('>', mainAt);
  const mainEnd = html.indexOf(mainClose, mainAt);
  const titleEnd = html.indexOf(titleClose, titleAt);
  const stamp = value(stampTag, 0);
  const shell = value(shellTag, 0);
  const body = value(bodyTag, mainAt);
  if (mainTagEnd < 0 || mainEnd < mainTagEnd || titleEnd < 0) return { kind: 'foreign' };
  if (stamp === undefined || stamp === '' || shell === undefined || body === undefined) return { kind: 'foreign' };
  if (stamp === current) return { kind: 'unchanged' };
  return {
    kind: 'update',
    stamp,
    shell,
    body,
    title: html.slice(titleAt + titleOpen.length, titleEnd),
    main: html.slice(mainTagEnd + 1, mainEnd)
  };
}

export function liveUpdateScript(): string {
  return `
    ${planIndexUpdate.toString()}
    (function () {
      var stamp = document.querySelector('header time');
      var header = document.querySelector('header');
      var announcer = document.getElementById('index-announcer');
      var warning = document.getElementById('index-stale');
      if (!stamp || !header) return;
      function localise(el) {
        var when = new Date(el.getAttribute('datetime') || '');
        if (!isNaN(when.getTime())) el.textContent = when.toLocaleString();
      }
      localise(stamp);
      // A table only needs to be reachable from the keyboard while it has
      // something off-screen to scroll to.
      function reachable() {
        var wraps = document.querySelectorAll('.table-wrap');
        for (var index = 0; index < wraps.length; index += 1) {
          if (wraps[index].scrollWidth > wraps[index].clientWidth) wraps[index].setAttribute('tabindex', '0');
          else wraps[index].removeAttribute('tabindex');
        }
      }
      reachable();
      window.addEventListener('resize', reachable);
      var paused = false;
      var toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'pause';
      // The name carries the state, so there is no aria-pressed to contradict
      // it: a toggle may change one or the other, never both.
      function label() { toggle.textContent = paused ? 'Resume updates' : 'Pause updates'; }
      // Opened from disk rather than through the router: fetch is blocked, so
      // the only thing left is to reload the whole file — and the reader still
      // gets to stop it.
      if (location.protocol === 'file:') {
        var reloadTimer;
        // A hidden tab is not being read; reloading it would only throw away
        // the reader's place before they come back to it.
        function again() {
          reloadTimer = setTimeout(function () {
            if (document.hidden) again(); else location.reload();
          }, ${NOSCRIPT_REFRESH_SECONDS * 1000});
        }
        toggle.addEventListener('click', function () {
          paused = !paused;
          label();
          if (paused) clearTimeout(reloadTimer); else again();
        });
        label();
        header.appendChild(toggle);
        again();
        return;
      }
      // Asked once: an engine that does not know the selector throws for it,
      // and a throw inside the loop is how a page stops updating for good.
      var knowsFocusVisible = (function () {
        try {
          document.documentElement.matches(':focus-visible');
          return true;
        } catch (error) {
          return false;
        }
      })();
      var inFlight = false;
      var failures = 0;
      var waiting = null;
      var reloaded = false;
      var timer;
      function schedule() { clearTimeout(timer); timer = setTimeout(tick, ${POLL_INTERVAL_MS}); }
      // Written only when it changes: it is a live region, and assigning the
      // same sentence every fifteen seconds announces it again.
      function marker(text, kind) {
        if (!warning || warning.textContent === text) return;
        warning.textContent = text;
        warning.className = kind;
      }
      // Four quiet failures is a page that has stopped working, not a blip.
      function failed() {
        failures = failures + 1;
        if (failures >= 4) marker('Not updating.', 'stale');
      }
      // Keyed by the shell it reloaded for, so a tab that sees two builds
      // alternate does not reload every fifteen seconds; the in-memory flag
      // covers a browser that refuses to store anything.
      function reloadOnce(shell) {
        var key = '${BRAND.name}-shell:' + shell;
        try {
          if (sessionStorage.getItem(key)) { marker('Not updating.', 'stale'); return; }
          sessionStorage.setItem(key, '1');
        } catch (error) {
          // Nothing can be remembered across a reload, so a reload cannot be
          // latched: reloading anyway is how a tab ends up reloading every
          // fifteen seconds with no way to stop it. Say so instead.
          marker('Not updating.', 'stale');
          return;
        }
        reloaded = true;
        location.reload();
      }
      function apply(main, plan) {
        waiting = null;
        if (plan.body !== main.getAttribute('data-body')) {
          main.innerHTML = plan.main;
          main.setAttribute('data-body', plan.body);
          reachable();
          if (announcer) announcer.textContent = plan.title + ' updated.';
        }
        if (failures === 0) marker('', '');
        stamp.setAttribute('datetime', plan.stamp);
        localise(stamp);
        document.title = plan.title;
      }
      // Only a keyboard reader loses their place to a swap. A click leaves
      // focus on the link just followed, and must not hold anything up.
      function held(main) {
        var active = document.activeElement;
        return !!(knowsFocusVisible && active && main.contains(active) &&
          active.matches && active.matches(':focus-visible'));
      }
      function tick() {
        clearTimeout(timer);
        // Once a reload is asked for this page is finished; a browser takes a
        // moment to act on it, and nothing should poll in the meantime.
        if (paused || inFlight || reloaded) return;
        try {
          var main = document.querySelector('main');
          // A hidden tab does not need the traffic.
          if (document.hidden || !main) { schedule(); return; }
          var request = { cache: 'no-cache', redirect: 'error' };
          if (typeof AbortSignal !== 'undefined' && AbortSignal.timeout) {
            request.signal = AbortSignal.timeout(10000);
          }
          inFlight = true;
          fetch(location.pathname, request)
            .then(function (response) {
              return response.ok ? response.text() : Promise.reject(new Error(String(response.status)));
            })
            .then(function (html) {
              var plan = planIndexUpdate(stamp.getAttribute('datetime'), html);
              // Something answered, but it is not this page: that is a failure
              // to read the index, however healthy the response looked.
              if (plan.kind === 'foreign') { failed(); return; }
              failures = 0;
              if (plan.kind === 'unchanged') { marker('', ''); return; }
              if (paused) return;
              // A newer berth wrote that page: its markup belongs to a
              // stylesheet and a script this tab does not have.
              if (plan.shell !== document.documentElement.getAttribute('data-shell')) {
                reloadOnce(plan.shell);
                return;
              }
              // Every regeneration moves the stamp, most change nothing on the
              // page: advance the clock quietly, and only swap — losing a
              // selection, spending an announcement — for a real change.
              // Reading inside the table: keep the rows rather than pulling
              // them out from under them, and put them in as soon as the
              // reader leaves. The stamp stays put until they are shown.
              if (plan.body !== main.getAttribute('data-body') && held(main)) {
                waiting = plan;
                marker('New rows waiting.', 'waiting');
                return;
              }
              apply(main, plan);
            })
            .catch(function () {
              // The router is down, or a regeneration is in flight: the next
              // tick will do. Say so only once it has clearly stopped working.
              failed();
            })
            .then(function () { inFlight = false; schedule(); });
        } catch (error) {
          // Nothing may leave the loop unarmed, and nothing may leave it
          // looking healthy while it fetches nothing.
          inFlight = false;
          failed();
          schedule();
        }
      }
      toggle.addEventListener('click', function () {
        paused = !paused;
        label();
        // The held rows are kept, but the marker promising them is not: while
        // paused nothing will put them in.
        if (paused) { clearTimeout(timer); if (waiting) marker('', ''); } else tick();
      });
      label();
      header.appendChild(toggle);
      document.addEventListener('visibilitychange', function () { if (!document.hidden && !paused) tick(); });
      // Rows held for a reader go in the moment they leave the table, rather
      // than waiting out the rest of the interval. Nothing is fetched here:
      // focus moves within a table would otherwise pull the page per keystroke.
      document.addEventListener('focusout', function () {
        if (paused || !waiting) return;
        // focusout runs before focus lands, so let it.
        setTimeout(function () {
          var main = document.querySelector('main');
          if (!paused && waiting && main && !held(main)) apply(main, waiting);
        }, 0);
      });
      schedule();
    })();
  `;
}

const STYLES = `
    :root { color-scheme: light dark; font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
    * { box-sizing: border-box; }
    body { margin: 0; min-width: 320px; color: #18212b; background: #f4f6f8; }
    header { display: flex; flex-wrap: wrap; align-items: end; justify-content: flex-end; gap: 8px 24px; padding: 28px 32px 20px; border-bottom: 1px solid #cbd2d9; background: #fff; }
    /* The margin, not justify-content: when the button wraps to its own line it
       must stay under the timestamp rather than jumping to the far corner. */
    h1 { margin: 0 auto 0 0; font-size: 24px; line-height: 1.2; }
    /* A domain, a project name or a path in a notice can be one long word;
       neither may push the page sideways. */
    h2 { margin: 28px 0 10px; font-size: 15px; color: #52606d; overflow-wrap: anywhere; }
    .updated { margin: 0; color: #52606d; font-size: 13px; }
    /* A visible border: this is the page's only control, and has to read as one. */
    .pause { padding: 5px 10px; border: 1px solid #7b8794; border-radius: 6px; background: #f4f6f8; color: #3e4c59; font: inherit; font-size: 12px; cursor: pointer; }
    .pause:hover { background: #e4e7eb; }
    main { padding: 4px 32px 32px; }
    /* A fixed layout with percentage columns always fits, so this is a net for
       content that somehow does not; the script keeps it keyboard-reachable
       if it ever catches something. */
    .table-wrap { overflow-x: auto; border: 1px solid #cbd2d9; border-radius: 6px; background: #fff; }
    .table-wrap:focus-visible { outline: 2px solid #075985; outline-offset: -2px; }
    table { width: 100%; border-collapse: collapse; table-layout: fixed; }
    thead th { padding: 10px 14px; color: #52606d; background: #eef1f4; font-size: 12px; font-weight: 700; text-align: left; text-transform: uppercase; }
    td, tbody th { padding: 14px; border-top: 1px solid #e4e7eb; font-size: 14px; font-weight: 400; text-align: left; vertical-align: top; }
    /* A long branch name has to break inside its fixed column, not run over the host. */
    tbody th { color: inherit; overflow-wrap: break-word; }
    /* Status is wide enough for the missing-checkout remedy to wrap at spaces, not mid-word. */
    thead th:nth-child(1) { width: 16%; } thead th:nth-child(2) { width: 21%; } thead th:nth-child(3) { width: 18%; } thead th:nth-child(4) { width: 17%; } thead th:nth-child(5) { width: 28%; }
    /* Fixed columns: a host with no hyphen must still break rather than overflow its cell. */
    code { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 12px; overflow-wrap: anywhere; }
    .path { display: block; overflow-wrap: anywhere; }
    .path-compact, .host-compact { display: none; }
    .stale { color: #7f1d1d; font-weight: 650; }
    .waiting { color: #52606d; font-weight: 650; }
    .legend { margin: 18px 2px 0; color: #52606d; font-size: 12px; }
    .muted { color: #5f6b7a; }
    .sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
    .services ul { margin: 0; padding: 0; list-style: none; }
    /* Stacked by default: two columns inside a quarter of the table starve each
       other, and a service name can be one unbreakable word. The min-width on
       the items is what lets them shrink at all — a grid item's own floor is
       its min-content width otherwise. */
    .service-link { display: grid; grid-template-columns: 1fr; gap: 0; margin: 0 -6px; padding: 4px 6px; border-radius: 4px; color: inherit; line-height: 1.35; text-decoration: none; }
    a.service-link:hover, a.service-link:focus-visible { background: #eef6f9; }
    /* Break anywhere in a service name, which can be one unbreakable word;
       prose has break opportunities a browser should be allowed to find. */
    .service-label { min-width: 0; overflow-wrap: anywhere; }
    .service-purpose { min-width: 0; overflow-wrap: break-word; hyphens: auto; }
    .service-label { color: #075985; font-weight: 650; text-decoration: underline; text-underline-offset: 3px; }
    .service-purpose { color: #52606d; font-size: 12px; }
    .service-disabled .service-label, .service-disabled .service-purpose { color: #5f6b7a; text-decoration: none; }
    .status { display: inline-block; min-width: 68px; padding: 3px 8px; border-radius: 999px; font-size: 12px; font-weight: 700; text-align: center; }
    .status-running { color: #14532d; background: #dcfce7; }
    .status-partial { color: #713f12; background: #fef3c7; }
    .status-stopped { color: #374151; background: #e5e7eb; }
    .status-missing { color: #7f1d1d; background: #fee2e2; }
    .status-unknown { color: #4c1d95; background: #ede9fe; }
    .guidance { margin-top: 7px; color: #7f1d1d; font-size: 11px; }
    /* The remedy is there to be read and copied: wrap between words where it can. */
    .guidance code { overflow-wrap: break-word; }
    .empty { padding: 36px; color: #52606d; text-align: center; }
    .notice { margin: 16px 0 0; padding: 10px 14px; border: 1px solid #f59e0b; border-radius: 6px; background: #fffbeb; color: #78350f; font-size: 13px; overflow-wrap: anywhere; }
    /* Where the two service columns start starving each other the table no
       longer fits either: shed the checkout column — it comes back under the
       branch, so nothing is unreachable — and stack the service text. */
    @media (max-width: 900px) {
      .checkout { display: none; }
      .path-compact { display: block; margin-top: 4px; color: #5f6b7a; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 11px; overflow-wrap: anywhere; }
      thead th:nth-child(1) { width: 26%; } thead th:nth-child(2) { width: 22%; } thead th:nth-child(4) { width: 22%; } thead th:nth-child(5) { width: 30%; }
      .service-purpose { font-size: 11px; }
    }
    @media (max-width: 640px) {
      header, main { padding-left: 16px; padding-right: 16px; }
      thead th { padding-left: 8px; padding-right: 8px; }
      td, tbody th { padding: 10px 8px; }
      thead th:nth-child(1) { width: 28%; } thead th:nth-child(2) { width: 22%; } thead th:nth-child(4) { width: 24%; } thead th:nth-child(5) { width: 26%; }
      /* The pill has to fit inside its cell at phone widths, not spill into the services. */
      .status { min-width: 0; padding: 3px 6px; }
    }
    /* The narrowest the page claims to support, which is also 400% zoom on a
       1280px window: the status word needs most of what the path gives up. */
    @media (max-width: 400px) {
      /* A hostname in a 35px column reads four characters at a time; under the
         branch it reads whole, and nothing has to scroll to it. */
      .host { display: none; }
      .host-compact { display: block; margin-top: 4px; }
      thead th:nth-child(1) { width: 42%; } thead th:nth-child(4) { width: 30%; } thead th:nth-child(5) { width: 28%; }
    }
    @media (prefers-color-scheme: dark) {
      body { color: #e5e7eb; background: #111827; }
      header, .table-wrap { background: #1f2937; border-color: #374151; }
      thead th { color: #9ca3af; background: #111827; }
      td, tbody th { border-color: #374151; }
      h2, .updated, .legend, .service-purpose { color: #9ca3af; }
      .muted, .service-disabled .service-label, .service-disabled .service-purpose, .path-compact { color: #9ca3af; }
      .pause { background: #111827; border-color: #7b8794; color: #e5e7eb; }
      .pause:hover { background: #374151; }
      .service-label { color: #7dd3fc; }
      a.service-link:hover, a.service-link:focus-visible { background: #0c4a6e; }
      a.service-link:hover .service-purpose, a.service-link:focus-visible .service-purpose { color: #cbd5e1; }
      .status-running { color: #bbf7d0; background: #14532d; }
      .status-partial { color: #fde68a; background: #713f12; }
      .status-stopped { color: #e5e7eb; background: #374151; }
      .status-missing { color: #fecaca; background: #7f1d1d; }
      .status-unknown { color: #ddd6fe; background: #4c1d95; }
      .guidance, .stale { color: #fca5a5; }
      .waiting { color: #9ca3af; }
      .table-wrap:focus-visible { outline-color: #7dd3fc; }
      .empty { color: #9ca3af; }
      .notice { background: #451a03; border-color: #92400e; color: #fde68a; }
    }
`;

/**
 * Docker could not be asked, so nothing below was checked — except that a
 * checkout is gone, which Git answers on its own and the page still shows.
 */
function dockerNotice(reason: string | undefined): string {
  return 'Docker could not be asked about containers, so no service below has been checked' +
    `${reason === undefined ? '' : `: ${reason}`}. ` +
    `Rows show Unknown unless Git reports the checkout gone. Run \`${BRAND.name} index\` again once it answers.`;
}

function identityNotice(failure: IdentityFailure): string {
  // Whatever Git said is prose, not markup: its own backticks would otherwise
  // pair with this sentence's and wrap the wrong span in a code span.
  const reason = failure.reason.replaceAll('`', "'");
  const consequence = failure.rowsUnknown
    ? 'Its rows show Unknown rather than Missing.'
    : 'No checkout below could be compared against it, so none is reported missing.';
  return `Checkout state unavailable for the repository that last regenerated this page — ${reason}. ` +
    `${consequence} Run \`${BRAND.name} index\` from one of its checkouts once Git can list them again.`;
}

const EMPTY_STATE = `No checkouts have been indexed yet. Run \`${BRAND.name} up\` in a worktree.`;

/** Backticked command spans, the one piece of markup these notices carry. */
function withCode(text: string): string {
  return escapeHtml(text).replaceAll(/`([^`]+)`/g, '<code>$1</code>');
}

export function renderIndexHtml(snapshot: IndexSnapshot): string {
  // The id counts sections rather than naming the domain: a registry record's
  // domain is not validated as a hostname, and a space in one would make the
  // reference two tokens that name nothing.
  const tables = sections(snapshot.entries).map((section, index) => {
    const heading = escapeHtml(section.heading);
    const id = `checkouts-${index}`;
    return `
    <section>
      <h2 id="${id}">${heading}</h2>
      <!-- The script makes this focusable if it ever scrolls; a region that
           does not scroll would only be a tab stop that does nothing. -->
      <div class="table-wrap" role="region" aria-labelledby="${id}">
        <table>
          <thead><tr><th scope="col">Branch</th><th scope="col" class="host">Host</th><th scope="col" class="checkout">Checkout</th><th scope="col">Status</th><th scope="col">Services</th></tr></thead>
          <tbody>${section.entries.map((entry) => renderRow(entry, !snapshot.dockerReachable && entry.status !== 'missing')).join('\n')}</tbody>
        </table>
      </div>
    </section>`;
  }).join('\n');
  const notices = [
    ...(snapshot.dockerReachable ? [] : [dockerNotice(snapshot.dockerError)]),
    ...(snapshot.identityError === undefined ? [] : [identityNotice(snapshot.identityError)])
  ].map((notice) => `<p class="notice">${withCode(notice)}</p>`).join('');
  // One legend for the page, above the tables: the same five words explain
  // every project, and a reader should not have to scroll to find them.
  // Both notices describe the rows, so neither is said when there are none.
  const body = snapshot.entries.length === 0
    ? `<p class="empty">${withCode(EMPTY_STATE)}</p>`
    : `${notices}<p class="legend">${LEGEND}</p>${tables}`;
  const script = liveUpdateScript();
  // The script is fixed at render time, so its hash can be too: the page then
  // declares exactly one executable thing and no network destination but itself.
  const scriptHash = createHash('sha256').update(script, 'utf8').digest('base64');
  // Everything a swapped-in table is rendered by. A tab that fetches a page
  // built by a different berth reloads rather than styling new markup with old
  // rules; the version number cannot do this job, since a rebuild need not
  // bump one to change the page.
  const shell = createHash('sha256').update(STYLES + script, 'utf8').digest('base64url').slice(0, 16);
  // What the rows say, so a tab can tell a regeneration that changed something
  // from one that only moved the clock — on its very first poll, which a
  // remembered copy of the last fetch cannot do.
  // Hashed over exactly what lands between the tags, so a tab comparing this
  // against what it fetched is comparing the same bytes.
  const rows = `${body}\n  `;
  const fingerprint = createHash('sha256').update(rows, 'utf8').digest('base64url').slice(0, 16);
  return `<!doctype html>
<html lang="en" data-shell="${shell}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'sha256-${scriptHash}'; connect-src 'self'; form-action 'none'; base-uri 'none'">
  <noscript><meta http-equiv="refresh" content="${NOSCRIPT_REFRESH_SECONDS}"></noscript>
  <title>${escapeHtml(pageTitle(snapshot))}</title>
  <style>${STYLES}  </style>
</head>
<body>
  <header>
    <h1>Checkouts</h1>
    <p class="updated">Updated <time datetime="${escapeHtml(snapshot.generatedAt)}">${escapeHtml(snapshot.generatedAt)}</time> <span class="stale" id="index-stale" role="status"></span></p>
  </header>
  <p class="sr-only" id="index-announcer" aria-live="polite"></p>
  <main data-body="${fingerprint}">${rows}</main>
  <script>${script}</script>
</body>
</html>
`;
}

/** Folds at spaces to fit a terminal. A word longer than the width is left whole. */
export function wrapText(text: string, width: number): string {
  const lines: string[] = [];
  let line = '';
  for (const word of text.split(' ')) {
    const candidate = line === '' ? word : `${line} ${word}`;
    if (candidate.length > width && line !== '') {
      lines.push(line);
      line = word;
    } else {
      line = candidate;
    }
  }
  if (line !== '') lines.push(line);
  return lines.join('\n');
}

// Prose folds at this; a path or a URL never does, because a reader has to be
// able to copy one off the line whole.
const TEXT_WIDTH = 78;
/** `!` is a state that was read, `?` one that could not be, `-` a checkout that is gone. */
const SERVICE_MARKERS = { available: '  ', unavailable: '! ', unchecked: '? ', gone: '- ' } as const;

export function formatIndexText(snapshot: IndexSnapshot, url: string): string {
  const groups = sections(snapshot.entries).map((section) => {
    const rows = section.entries.map((entry) => {
      const unchecked = !snapshot.dockerReachable && entry.status !== 'missing';
      const services = entry.services.length === 0
        ? '    (no services)'
        : entry.services.map((service) => {
          const marker = entry.status === 'missing'
            ? SERVICE_MARKERS.gone
            : unchecked
              ? SERVICE_MARKERS.unchecked
              : service.available ? SERVICE_MARKERS.available : SERVICE_MARKERS.unavailable;
          const named = printable(service.purpose === '' ? service.label : `${service.label} (${service.purpose})`);
          const link = printable(service.url);
          const line = `    ${marker}${named.padEnd(28)} ${link}`;
          if (line.length <= TEXT_WIDTH) return line;
          // The URL is the one thing worth double-clicking, so it never shares a
          // line it would be wrapped out of; it is indented past the names so a
          // continuation cannot be read as another service.
          const [first = '', ...rest] = wrapText(named, TEXT_WIDTH - 8).split('\n');
          // Continuations sit at the URL's column, never at the column a
          // service name starts in, where they would read as another service.
          return [`    ${marker}${first}`, ...rest.map((part) => `        ${part}`), `        ${link}`].join('\n');
        }).join('\n');
      return [
        // The status leads: a branch name is one unbreakable token, so trailing
        // it would push the state off an eighty-column terminal.
        `  [${STATUS_LABELS[entry.status]}]  ${printable(describeBranch(entry.branch).text)}`,
        indented('    host      ', printable(entry.host)),
        // A path, like a host or a URL, is left whole however long it is: each is
        // a single token, there to be copied.
        `    checkout  ${entry.root === undefined ? '-' : printable(compactPath(entry.root))}`,
        // The same remedy the page offers, for whoever is reading this over SSH.
        // One command, never folded: it is there to be copied.
        ...(entry.status === 'missing'
          ? [`    gone      ${BRAND.name} worktree remove ${printable(entry.slug)}`]
          : []),
        services
      ].filter(Boolean).join('\n');
    }).join('\n\n');
    return `${wrapText(printable(section.heading), TEXT_WIDTH)}\n${rows}`;
  }).join('\n\n');
  const head = `Checkout index  ${printable(url)}\nUpdated         ${printable(snapshot.generatedAt)}\n`;
  if (snapshot.entries.length === 0) return `${head}\n${wrapText(EMPTY_STATE, TEXT_WIDTH)}`;
  const notices = [
    ...(snapshot.dockerReachable ? [] : [dockerNotice(snapshot.dockerError)]),
    ...(snapshot.identityError === undefined ? [] : [identityNotice(snapshot.identityError)])
  ].map((notice) => `${wrapText(printable(notice), TEXT_WIDTH)}\n\n`).join('');
  const legend = `${wrapText(LEGEND, TEXT_WIDTH)}\nServices: ! not answering, ? not checked, - checkout gone.\n\n`;
  return `${head}\n${notices}${legend}${groups}`;
}

/** A labelled line whose continuation lines sit under the value, not the label. */
function indented(label: string, value: string): string {
  const [first = '', ...rest] = wrapText(value, TEXT_WIDTH - label.length).split('\n');
  return [`${label}${first}`, ...rest.map((part) => `${' '.repeat(label.length)}${part}`)].join('\n');
}
